import React, { useEffect, useState } from "react";
import { stats } from "../data/portfolioData";
import profilePic from "../assets/695845981_1656532365494890_4681825014942848380_n.jpg";

const ROLES = [
  "Full Stack Developer",
  "React Engineer",
  "Node.js Developer",
  "TypeScript Enthusiast",
  "Open Source Contributor",
];

export default function Hero() {
  const [roleIdx, setRoleIdx] = useState(0);
  const [displayed, setDisplayed] = useState("");
  const [typing, setTyping] = useState(true);

  useEffect(() => {
    const role = ROLES[roleIdx];

    if (typing) {
      if (displayed.length < role.length) {
        const t = setTimeout(
          () => setDisplayed(role.slice(0, displayed.length + 1)),
          60
        );
        return () => clearTimeout(t);
      } else {
        const t = setTimeout(() => setTyping(false), 1800);
        return () => clearTimeout(t);
      }
    } else {
      if (displayed.length > 0) {
        const t = setTimeout(
          () => setDisplayed(displayed.slice(0, -1)),
          35
        );
        return () => clearTimeout(t);
      } else {
        setRoleIdx((i) => (i + 1) % ROLES.length);
        setTyping(true);
      }
    }
  }, [displayed, typing, roleIdx]);

  return (
    <section
      id="hero"
      className="relative min-h-screen flex items-center justify-center px-6 pt-24 pb-16 overflow-hidden"
    >
      {/* Background */}
      <div className="absolute inset-0 bg-bg-primary" />

      <div
        className="absolute inset-0 opacity-30"
        style={{
          backgroundImage:
            "linear-gradient(rgba(96,165,250,0.08) 1px, transparent 1px), linear-gradient(90deg, rgba(96,165,250,0.08) 1px, transparent 1px)",
          backgroundSize: "56px 56px",
        }}
      />

      {/* MAIN LAYOUT */}
      <div className="relative z-10 max-w-6xl mx-auto flex flex-col md:flex-row items-center gap-12">

        {/* LEFT SIDE IMAGE */}
        <div className="flex-1 flex justify-center md:justify-start">
          <div className="relative">

            {/* glow */}
            <div className="absolute inset-0 rounded-2xl bg-accent-blue/20 blur-2xl animate-pulse"></div>

            {/* image */}
            <img
              src={profilePic}
              alt="Profile"
              className="relative w-64 h-64 md:w-80 md:h-80 object-cover rounded-2xl border-4 border-accent-blue shadow-2xl"
            />

            {/* online dot */}
            <div className="absolute bottom-3 right-3 w-5 h-5 bg-green-500 rounded-full border-2 border-bg-primary animate-pulse"></div>
          </div>
        </div>

        {/* RIGHT SIDE CONTENT */}
        <div className="flex-1 text-center md:text-left">

          {/* badge */}
          <div className="inline-flex items-center gap-3 mb-6 px-4 py-2 rounded-full border border-accent-blue/20 bg-accent-blue/5">
            <span className="w-2 h-2 rounded-full bg-accent-green animate-pulse" />
            <span className="font-mono text-xs text-slate-400 tracking-widest uppercase">
              Available for hire
            </span>
          </div>

          {/* name */}
          <h1
            className="font-mono font-bold leading-tight mb-6"
            style={{ fontSize: "clamp(2.5rem, 6vw, 4.5rem)" }}
          >
            <span className="text-white">Hi, I'm </span>
            <span className="text-gradient">
              K.Milinda Nirwan Premathilaka
            </span>
            <br />
            <span className="text-white">I build </span>
            <span className="text-accent-blue">full-stack</span>
            <br />
            <span className="text-white">products.</span>
          </h1>

          {/* typewriter */}
          <div className="font-mono text-lg text-slate-400 mb-6 h-8 flex items-center gap-1 justify-center md:justify-start">
            <span className="text-accent-cyan">&gt;</span>
            <span className="text-slate-300">{displayed}</span>
            <span className="inline-block w-0.5 h-5 bg-accent-blue animate-blink" />
          </div>

          {/* description */}
          <p className="text-slate-400 text-lg mb-10 leading-relaxed max-w-xl">
            I craft{" "}
            <span className="text-white font-medium">
              end-to-end web applications
            </span>{" "}
            — from database schemas to pixel-perfect UIs. I care about{" "}
            <span className="text-white font-medium">performance</span> and{" "}
            <span className="text-white font-medium">scalability</span>.
          </p>

          {/* buttons */}
          <div className="flex flex-wrap gap-4 justify-center md:justify-start">
            <button
              onClick={() =>
                document
                  .querySelector("#projects")
                  ?.scrollIntoView({ behavior: "smooth" })
              }
              className="px-6 py-3 rounded-xl bg-accent-blue text-bg-primary font-mono font-bold hover:scale-105 transition"
            >
              View my work
            </button>

            <a
              href="/resume.pdf"
              className="px-6 py-3 rounded-xl border border-white/10 text-slate-300 font-mono hover:text-white hover:border-accent-blue/40 transition"
            >
              Download CV
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}
